<?php
declare(strict_types=1);
$root=dirname(__DIR__);
function read_json(string $p):array{$v=json_decode((string)file_get_contents($p),true);if(!is_array($v))throw new RuntimeException('JSON inválido: '.$p);return $v;}
$original=read_json($root.'/resultados/original/resultados.json');$fase1=read_json($root.'/resultados/fase1/resultados.json');
$omap=[];foreach($original['results'] as $r)$omap[$r['test']]=$r;$fmap=[];foreach($fase1['results'] as $r)$fmap[$r['test']]=$r;
$rows=[];$mandatoryFails=[];foreach($fmap as $id=>$fr){$or=$omap[$id]??null;$rows[]=['test'=>$id,'name'=>$fr['name'],'original'=>$or['status']??'NO_DATA','fase1'=>$fr['status'],'expected'=>$fr['expected'],'mandatory'=>$fr['mandatory'],'conclusion'=>$fr['status']==='PASS'?'Cumple':($fr['status']==='KNOWN_FAILURE'?'Defecto conocido pendiente':'No cumple')];if($fr['mandatory']&&$fr['status']!=='PASS')$mandatoryFails[]=$id;}
$apiOriginal=read_json($root.'/resultados/original/api_publica.json');$apiFase1=read_json($root.'/resultados/fase1/api_publica.json');unset($apiOriginal['version'],$apiFase1['version']);$apiEqual=$apiOriginal==$apiFase1;
file_put_contents($root.'/resultados/comparacion/api_publica.json',json_encode(['equal'=>$apiEqual,'original'=>$apiOriginal,'fase1'=>$apiFase1],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
