$validated=count($mandatoryFails)===0&&$apiEqual&&$hashOk;
$summary=['validated'=>$validated,'mandatory_failures'=>$mandatoryFails,'api_equal'=>$apiEqual,'hashes_unchanged'=>$hashOk,'rows'=>$rows];
