$md="# INFORME DE PRUEBAS DE LA FASE 1\n\n";
$extensions=get_loaded_extensions();sort($extensions);$phaseSummary=$fase1['summary'];$phpunitExecuted=is_file($root.'/resultados/phpunit.xml');
$md.="- Fecha: ".date(DATE_ATOM)."\n- PHP ejecutado: ".PHP_VERSION."\n- Sistema: ".PHP_OS_FAMILY." (".php_uname().")\n- HTTP probado: ".(getenv('SHD_HTTP_BASE') ?: 'http://127.0.0.1:8080')."\n- HTTPS probado: ".(getenv('SHD_HTTPS_BASE') ?: 'https://127.0.0.1:8443')."\n- Extensiones: ".implode(', ',$extensions)."\n- Fase validada: **".($validated?'SÍ':'NO')."**\n- API pública idéntica: ".($apiEqual?'Sí':'No')."\n- Librerías sin modificaciones: ".($hashOk?'Sí':'No')."\n- Pruebas fase 1: ".$phaseSummary['total']." totales; ".$phaseSummary['pass']." aprobadas; ".$phaseSummary['fail']." fallidas; ".$phaseSummary['known_failure']." defectos conocidos.\n- PHPUnit: ".($phpunitExecuted?'Ejecutado; consulte resultados/phpunit.xml':'No ejecutado en este entorno; runner autónomo ejecutado')."\n- Fallos obligatorios: ".(count($mandatoryFails)?implode(', ',$mandatoryFails):'ninguno')."\n\n";
$md.="| Prueba | Original | Fase 1 | Obligatoria | Conclusión |\n|---|---:|---:|---:|---|\n";foreach($rows as $r){$md.='| '.$r['test'].' '.$r['name'].' | '.$r['original'].' | '.$r['fase1'].' | '.($r['mandatory']?'Sí':'No').' | '.$r['conclusion']." |\n";}
$md.="\n## Conclusión\n\n".($validated?'Las correcciones obligatorias de la fase 1 quedan validadas en el entorno ejecutado.':'La fase 1 no puede declararse validada hasta resolver los fallos obligatorios indicados.')."\n";
file_put_contents($root.'/INFORME_PRUEBAS_FASE_1.md',$md);
$cmp="# COMPARACIÓN ORIGINAL / FASE 1\n\n| Prueba | Original | Fase 1 | Resultado esperado | Conclusión |\n|---|---:|---:|---|---|\n";foreach($rows as $r){$exp=str_replace(["\r","\n","|"],[' ',' ','\\|'],is_scalar($r['expected'])?(string)$r['expected']:json_encode($r['expected'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$cmp.='| '.$r['test'].' | '.$r['original'].' | '.$r['fase1'].' | '.$exp.' | '.$r['conclusion']." |\n";}file_put_contents($root.'/COMPARACION_ORIGINAL_FASE1.md',$cmp);
$known=array_filter($rows,fn($r)=>str_starts_with($r['test'],'K-'));$err="# ERRORES DETECTADOS\n\n## Errores del original corregidos o evidenciados\n\n";foreach($rows as $r){if($r['original']!=='PASS'&&$r['fase1']==='PASS')$err.='- '.$r['test'].': '.$r['name'].".\n";}$err.="\n## Regresiones introducidas por fase 1\n\n"; $reg=[];foreach($rows as $r){if($r['original']==='PASS'&&$r['fase1']==='FAIL')$reg[]=$r;} $err.=count($reg)?implode("\n",array_map(fn($r)=>'- '.$r['test'].': '.$r['name'].'.',$reg))."\n":"No se detectaron en la ejecución actual.\n";$err.="\n## Defectos conocidos pendientes\n\n";foreach($known as $r)$err.='- '.$r['test'].': '.$r['name'].' — '.$r['fase1'].".\n";$err.="\n## Problemas del entorno\n\nConsulte `LIMITACIONES_DEL_ENTORNO.md`.\n";file_put_contents($root.'/ERRORES_DETECTADOS.md',$err);
$matrix="# MATRIZ DE COMPATIBILIDAD\n\n| PHP | Ejecutado | Resultado | Observaciones |\n|---|---:|---|---|\n| 7.4 | No | No afirmado | No disponible en este entorno |\n| 8.0 | No | No afirmado | No disponible en este entorno |\n| 8.1 | No | No afirmado | No disponible en este entorno |\n| 8.2 | No | No afirmado | No disponible en este entorno |\n| 8.3 | No | No afirmado | No disponible en este entorno |\n| ".PHP_MAJOR_VERSION.'.'.PHP_MINOR_VERSION." | Sí | ".($validated?'Validado':'No validado')." | Versión exacta ".PHP_VERSION." |\n| 8.5 | ".(PHP_MAJOR_VERSION===8&&PHP_MINOR_VERSION===5?'Sí':'No')." | ".(PHP_MAJOR_VERSION===8&&PHP_MINOR_VERSION===5?($validated?'Validado':'No validado'):'No afirmado')." | Objetivo futuro |\n";file_put_contents($root.'/MATRIZ_COMPATIBILIDAD.md',$matrix);
exit($validated?0:1);
